-- @marker SEED-10-12
-- 대상 IT-10-058 IT-10-059 IT-10-060 IT-10-062 IT-10-066
-- 분석 단계이고 입찰 분석이 끝난 입찰 건들. 분석 완료 본문은 시험항목 items_10 의 REPORT_BODY, CAPTURE_BODY, DECISION_BODY 를
-- 서버 save_bid_analysis 로 저장해 얻은 값 그대로다(Pwin 72.0, Strong Go). 1번 회차를 원본으로 두고 나머지는 베낀다
-- 1, 2번은 읽지 못한 서류 하나가 남은 건(다시 읽기 몫이라 실제 PDF 를 놓는다), 4번은 아무것도 저장하지 않은 분석 중 회차라
-- 서버 판정이 그 회차에 세 산출물을 저장해 서버 계산을 본다. 6, 7번은 관리자 결정 Go, 8번은 결정 저장 없이 끝난 분석 실패다
-- 분석 중 회차는 워크플로우 대기 한도(10/25 상용 60분) 안이어야 하므로 키는 50분 안에 시작한 것만 준다. 대기 한도를 50분 아래로 줄이면 이 창도 줄인다
-- @file seed/10-12/1.pdf past-performance.pdf
-- @file seed/10-12/2.pdf past-performance.pdf
-- @key 10.b058_server_bid SELECT '[[uuid:03:1]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:1]] AND state = 'ANALYZING'
-- @key 10.b058_virtual_bid SELECT '[[uuid:03:2]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:2]] AND state = 'ANALYZING'
-- @key 10.b059_virtual_bid SELECT '[[uuid:03:3]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:3]] AND state = 'ANALYZING'
-- @key 10.b060_server_bid SELECT '[[uuid:03:4]]' AS id, HEX(id) AS hex, '[[uuid:0c:4]]' AS analysis FROM bid_requests WHERE id = [[id:03:4]] AND state = 'ANALYZING' AND EXISTS (SELECT 1 FROM bid_analyses ba WHERE ba.id = [[id:0c:4]] AND (ba.status <> 'RUNNING' OR ba.started_at >= [[now]] - INTERVAL 50 MINUTE))
-- @key 10.b060_virtual_bid SELECT '[[uuid:03:5]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:5]] AND state = 'ANALYZING'
-- @key 10.b062_server_bid SELECT '[[uuid:03:6]]' AS id, HEX(id) AS hex, '[[uuid:0c:6]]' AS analysis FROM bid_requests WHERE id = [[id:03:6]]
-- @key 10.b062_virtual_bid SELECT '[[uuid:03:7]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:7]] AND state = 'ANALYZING'
-- @key 10.b066_virtual_bid SELECT '[[uuid:03:8]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:8]] AND state = 'ANALYZING'
